.notifications__actions .button--danger { background: transparent !important; border-color: transparent !important; color: #ff99a4 !important; }
.notifications__actions .button--danger:hover { background: rgba(255, 153, 164, .1) !important; }

.notifications__list { display: flex !important; flex-direction: column; gap: 0 !important; padding: 4px !important;
  background: rgba(255, 255, 255, .05); border: 1px solid rgba(255, 255, 255, .07); border-radius: 14px; }
.notification-item {
  position: relative; display: grid !important; grid-template-columns: 40px minmax(0, 1fr) auto; column-gap: 14px; align-items: center;
  padding: 12px 44px 12px 24px !important; margin: 0 !important; min-height: 68px; box-sizing: border-box;
  background: transparent !important; border: 0 !important; border-radius: 10px !important; opacity: 1 !important; box-shadow: none !important;
