.notification-item:hover::after, .notification-item:hover + .notification-item::after { opacity: 0; }
.notification-item--unread::before { content: ""; position: absolute; left: 9px; top: 50%; width: 7px; height: 7px; margin-top: -3.5px; border-radius: 50%; background: var(--accent-bright); }
