.similar-games__card:hover { background: transparent !important; border-color: transparent !important; }
.similar-games__card:hover img, .similar-games__card:hover .vertical-cover-card__image { transform: translateY(-4px) !important; transition: transform .6s cubic-bezier(.16, 1, .3, 1), box-shadow .6s cubic-bezier(.16, 1, .3, 1), border-color .3s, filter .4s !important; }
.similar-games__card::after, .similar-games__card::before { display: none !important; content: none !important; }
/* Título em texto (jogo sem logo): uma linha larga em vez de três estreitas,
   tamanho menor, peso de display e sombra suave para ler sobre a arte. */
.game-details__game-logo-text {
  max-width: min(900px, 70%) !important; width: auto !important;
  font: 700 clamp(32px, 3.4vw, 48px)/1.1 var(--font-display) !important; letter-spacing: -.02em;
  color: #fff !important; text-shadow: 0 2px 20px rgba(0, 0, 0, .45);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: balance;
}
.game-details__hero-standard-meta:has(.game-details__game-logo-text) { max-width: none !important; width: 100% !important; }
/* Carrossel de similares: mesma área com e sem hover (antes o hover zerava a margem lateral e as capas encolhiam) */
.similar-games .similar-games__viewport, .similar-games .similar-games__viewport:has(.similar-games__card:hover) { padding: 10px 0 8px !important; margin: -10px -6px -8px !important; }
/* Similares: volta o brilho que atravessa a capa no hover (como no catálogo);
   ele acompanha a capa subindo e usa o mesmo canto arredondado. */
.similar-games__card::after {
  display: block !important; content: "" !important; position: absolute; inset: 0; z-index: 2; pointer-events: none; border-radius: var(--r-surface);
  background: linear-gradient(115deg, transparent 35%, rgba(255, 255, 255, .55) 48%, rgba(255, 255, 255, .15) 55%, transparent 65%) 130% 0 / 250% 100% no-repeat;
  mix-blend-mode: overlay; opacity: 0; transition: background-position 0s .3s, opacity .3s var(--ease), transform .6s cubic-bezier(.16, 1, .3, 1);
}
.similar-games__card:hover::after { background-position: -30% 0; opacity: 1; transform: translateY(-4px); transition: background-position .9s var(--ease), opacity .3s var(--ease), transform .6s cubic-bezier(.16, 1, .3, 1); }
.similar-games__card { position: relative; }
/* Similares com a animação idêntica à das capas da Biblioteca: o cartão inteiro
   sobe 4px (.6s), a borda acende, a sombra aparece, a arte ganha cor e o
   brilho atravessa só na entrada do mouse. */
.similar-games .similar-games__card {
  position: relative; border-radius: var(--r-surface) !important; isolation: isolate; border: 1px solid var(--card-stroke) !important;
  transition: transform .6s cubic-bezier(.16, 1, .3, 1), box-shadow .6s cubic-bezier(.16, 1, .3, 1), border-color .3s ease !important;
}
.similar-games .similar-games__card:hover {
  transform: translateY(-4px) !important; border-color: rgba(255, 255, 255, .22) !important;
  box-shadow: 0 14px 28px rgba(0, 0, 0, .45), 0 0 0 1px rgba(255, 255, 255, .06) !important;
}
.similar-games .similar-games__card img, .similar-games .similar-games__card:hover img {
  transform: none !important; border: 0 !important; box-shadow: none !important; border-radius: calc(var(--r-surface) - 1px) !important;
  transition: filter .4s ease !important;
}
.similar-games .similar-games__card:hover img { filter: saturate(1.15) brightness(1.06) !important; }
.similar-games .similar-games__card::after { display: block !important; content: "" !important; position: absolute; inset: 0; z-index: 3; pointer-events: none; border-radius: inherit; transform: none !important; background: linear-gradient(115deg, transparent 35%, rgba(255, 255, 255, .55) 48%, rgba(255, 255, 255, .15) 54%, transparent 65%) !important; background-size: 260% 100% !important; mix-blend-mode: overlay; opacity: 0; transition: opacity .2s linear, background-position 0s linear .2s !important; }
.similar-games .similar-games__card:hover::after { opacity: 1 !important; transition: background-position .9s var(--ease), opacity .3s var(--ease) !important; }
