.friends-window__profile-name { font: 600 18px/24px var(--font-display) !important; color: #fff !important; text-shadow: 0 1px 8px rgba(0, 0, 0, .5); padding: 0 !important; background: none !important; border: 0 !important; height: auto !important; }
