   do destaque, cartões grandes com faixa de vidro. */
/* Bordas iguais às do cabeçalho */

.home__header, .home__title, .home__cards { padding-left: 0; padding-right: 0; margin-left: 0; margin-right: 0; }

/* Abas: controle segmentado do tema */
.home__header { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 0; padding-bottom: 0; height: auto; }
.home__buttons-list { display: flex; gap: 2px; padding: 2px; margin: 0; list-style: none; background: rgba(0, 0, 0, 0.113); border: 1px solid rgba(0, 0, 0, 0.051); border-radius: calc(var(--ctl-r) + 2px); }
.home__buttons-list .button { height: 30px; min-height: 30px; padding: 0 12px; gap: 8px; border-radius: var(--ctl-r); background: transparent;
  border: 1px solid transparent; color: var(--text-2); font: 400 14px/20px var(--font); box-shadow: none; }
.home__buttons-list .button:hover { background: rgba(0, 0, 0, 0.036) !important; color: var(--text) !important; }

.home__buttons-list .button--primary svg, .home__buttons-list .button--primary img { color: var(--accent-bright); }

.home__title-icon { display: none; }
/* Cartões de jogo: arte limpa, info em vidro na base */
.game-card { border-radius: var(--r-surface); border: 1px solid rgba(255,255,255,.08); overflow: hidden; isolation: isolate; box-shadow: 0 4px 12px rgba(0,0,0,.25);
