.game-card:hover .game-card__cover { transform: scale(1.04); }

.home__buttons-list .button > svg:first-child:not(:only-child) { display: none; }



/* Destaque: arte em tela cheia por trás do cabeçalho, sumindo no fundo */
.home__content {
  padding-left: 16px;
  padding-right: 16px;
  box-sizing: border-box;
  padding-top: 0;
}
.hero { position: relative; max-height: none; margin: -79px -16px 0; width: calc(100% + 32px); border-radius: 0; border: 0; overflow: hidden; background: none; box-shadow: none; }

.hero__media { border-radius: 0; object-position: center 30%; animation: mica-hero-drift 24s ease-in-out infinite alternate; }
@keyframes mica-hero-drift { from { transform: scale(1.02); } to { transform: scale(1.08) translateX(-1%); } }
@media (prefers-reduced-motion: reduce) { .hero__media { animation: none; } }
.hero__content { padding: 0 48px 108px; justify-content: flex-end; }

.hero:hover .hero__logo { transform: scale(1.02); }
.hero__description { max-width: 580px; font: 400 15px/24px var(--font) !important; color: rgba(0, 0, 0, 0.82); margin: 0;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.225); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; height: auto; max-height: none; }

/* Abas flutuando sobre a base do destaque, em vidro */
.home__header { margin: -76px 32px 0 !important; padding: 8px !important; border-radius: 14px; background: rgba(247, 247, 247, .45); border: 1px solid rgba(0, 0, 0, 0.085); backdrop-filter: blur(24px) saturate(1.7); -webkit-backdrop-filter: blur(24px) saturate(1.7); box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.051), 0 8px 24px rgba(0, 0, 0, 0.135); }
.home__header > .button { height: 32px; min-height: 32px; padding: 0 12px; gap: 8px; border-radius: var(--ctl-r);
  background: var(--ctl-bg); border: 1px solid var(--ctl-stroke); color: var(--text); font: var(--ctl-font); box-shadow: none; }
.home__header > .button:hover { background: var(--ctl-bg-hover) !important; }

/* Seção */


/* Cartões: arte grande, faixa de vidro com nome e fontes */

.game-card { height: auto; aspect-ratio: 16 / 8.2; }
.game-card__backdrop {
  background: none;
  height: 100%;
}
.game-card__cover {
  transition: transform .4s var(--ease-out);
  width: 100%;
  height: 100%;
  object-fit: cover;
}


.game-card__download-options { gap: 8px; }
.hero__backdrop, .hero__media { height: 100%; max-height: none; }

.hero, .hero__backdrop { border-bottom: 0; outline: 0; }
/* O degradê some junto com a arte (sem degrau na base do destaque) */


.hero__backdrop {
  border-radius: 0;
  background: none;
  -webkit-mask-image: none;
  mask-image: none;
}
.hero__media {
  width: 100%;
  object-fit: cover;
  -webkit-mask-image: linear-gradient(180deg, #000 40%, rgba(0,0,0,.55) 68%, transparent 92%);
  mask-image: linear-gradient(180deg, #000 40%, rgba(0,0,0,.55) 68%, transparent 92%);
}
.hero__content { background: radial-gradient(ellipse 70% 60% at 0% 62%, rgba(0, 0, 0, 0.248), transparent 70%); }
/* As abas 2 e 3 já trazem um emoji no texto; o ícone extra duplicava */
.home__buttons-list li:not(:first-child) .button > svg { display: none !important; }
/* Mantém a fonte "Mica Blank" que esconde o emoji do texto das abas (o ícone do tema entra no lugar) */
.home__buttons-list .button { font-family: "Mica Blank", var(--font); }

/* Cartões do Início no padrão "arte limpa" da biblioteca: sem faixa,
   só um escurecimento curto na base, nome e fontes direto sobre a arte. */
.game-card__content { left: 0; right: 0; bottom: 0; top: auto; width: auto; padding: 40px 16px 14px; gap: 4px; border: 0; border-radius: 0; background: linear-gradient(0deg, rgba(0,0,0,.72), rgba(0,0,0,.35) 55%, transparent); backdrop-filter: none; -webkit-backdrop-filter: none !important; }
.game-card:hover .game-card__content { background: linear-gradient(0deg, rgba(0,0,0,.72), rgba(0,0,0,.35) 55%, transparent) !important; }
.game-card__title { font: 600 15px/20px var(--font) !important; color: #fff; text-shadow: 0 1px 6px rgba(0,0,0,.6); }
.game-card__download-options .badge {
  font: 600 10px/14px var(--font);
  letter-spacing: .04em;
  text-transform: uppercase;
  background: none;
  border: 0;
  padding: 0;
  color: rgba(255,255,255,.72);
  text-shadow: 0 1px 4px rgba(0,0,0,.6);
}

/* ---------- Início: acabamento ---------- */
/* 1. Abas presas logo abaixo do cabeçalho ao rolar */


/* 2. Destaque acompanha a altura da janela */
.hero { height: clamp(420px, 60vh, 640px); }

/* 3. Grade: 2 / 3 / 4 colunas conforme a largura */
.home__cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
@media (max-width: 1100px) { .home__cards { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1800px) { .home__cards { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

/* 4. Convite no destaque (último item do bloco de texto) */
.hero__content::after { white-space: pre; align-self: flex-start; height: 32px; padding: 0 14px; border-radius: var(--ctl-r); box-sizing: border-box; font: 600 13px/30px var(--font); color: #1b1b1b; background: rgba(0, 0, 0, 0.102); border: 1px solid rgba(0, 0, 0, 0.153); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); transition: background .15s, border-color .15s, color .15s; animation: mica-rise .5s .16s var(--ease-out) both; }
.hero:hover .hero__content::after { background: var(--accent); border-color: transparent; color: var(--on-accent); }


/* 5. Entrada */
@keyframes mica-rise { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
.hero__logo {
  width: auto;
  max-width: 420px;
  max-height: 160px;
  object-fit: contain;
  object-position: left bottom;
  filter: drop-shadow(0 6px 24px rgba(0, 0, 0, 0.248));
  transition: transform .4s var(--ease-out);
  transform-origin: left bottom;
  animation: mica-rise .5s var(--ease-out) both;
}
.hero__description { animation: mica-rise .5s .08s var(--ease-out) both; }
.home__cards > .game-card { animation: mica-rise .4s var(--ease-out) both; }
.home__cards > .game-card:nth-child(2) { animation-delay: .03s; } .home__cards > .game-card:nth-child(3) { animation-delay: .06s; }
.home__cards > .game-card:nth-child(4) { animation-delay: .09s; } .home__cards > .game-card:nth-child(5) { animation-delay: .12s; }
.home__cards > .game-card:nth-child(6) { animation-delay: .15s; } .home__cards > .game-card:nth-child(n + 7) { animation-delay: .18s; }
@media (prefers-reduced-motion: reduce) { .hero__logo, .hero__description, .home__cards > .game-card { animation: none; } }

/* 6. Números no hover, em selos de vidro no canto */
.game-card__specifics {
  display: flex; position: absolute; top: auto; bottom: 12px; right: 12px; gap: 6px; margin: 0;
  opacity: 0; transform: translateY(4px); transition: opacity .2s var(--ease-out), transform .2s var(--ease-out); pointer-events: none;
}
.game-card:hover .game-card__specifics { opacity: 1; transform: none; }
.game-card__content {
