  transform: translateY(0);
  transition: background .2s;
  position: absolute;
}
.game-card__specifics-item {
  display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 9px; border-radius: 999px; font: 600 11px/16px var(--font) !important; color: #fff;
  background: rgba(24,24,24,.55); border: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(16px);
}
.game-card__specifics-item svg { width: 12px; height: 12px; }

/* 7. Carregamento: blocos no formato dos cartões com brilho */
.home__card-skeleton { border-radius: var(--r-surface) !important; aspect-ratio: 16 / 8.2; height: auto !important; overflow: hidden; border: 1px solid rgba(0, 0, 0, 0.051);
  background: linear-gradient(100deg, rgba(0, 0, 0, 0.034) 30%, rgba(0, 0, 0, 0.076) 50%, rgba(0, 0, 0, 0.034) 70%) 0 0 / 300% 100% !important;
  animation: mica-shimmer 1.4s linear infinite; }
.home__card-skeleton .react-loading-skeleton { display: none; }
@keyframes mica-shimmer { from { background-position: 100% 0; } to { background-position: -50% 0; } }
@media (prefers-reduced-motion: reduce) { .home__card-skeleton { animation: none; } }
/* Abas presas a 8px do cabeçalho (o topo de rolagem já fica abaixo dele) */
.home__header {
  position: sticky;
  z-index: 5;
  transition: background .2s, box-shadow .2s;
  top: 9px;
}
/* Título da seção oculto: a aba ativa já diz qual lista é */
.home__title {
  
  
  font: 600 24px/32px var(--font-display) !important;
  margin: 32px 0 16px 4px !important;
  font-family: "Mica Blank", var(--font-display);
