  -webkit-mask-image: none;
  gap: 16px;
  padding-bottom: 108px;
}
/* Itens da lista sem fundo próprio (regra antiga pintava #2c2c2c em cada opção) */
select option, .select-field__option option { background: transparent; color: var(--text); }
select option:hover, select option:focus-visible, select option:checked { background: var(--ctl-bg) !important; }
select option:active { background: rgba(0, 0, 0, 0.034) !important; }
/* Ordenar do catálogo: mesma folga dos dois lados (ícone a 10px, seta a 10px) */
.catalogue__sort-select .select-field { padding: 0; }
.catalogue__sort-select .select-field__option { padding: 0 10px 0 32px; gap: 8px; }
.catalogue__sort-inline::before { left: 19px; }

/* Opções de download: título inteiro (quebra em quantas linhas precisar),
   detalhes à direita alinhados à primeira linha, sem cortar nada. */

.repacks-modal__repack-title { white-space: normal !important; overflow: visible !important; text-overflow: clip !important; max-height: none !important; align-self: start !important; overflow-wrap: anywhere; }
.repacks-modal__repack-info { align-self: start !important; line-height: 20px !important; font-size: 13px !important; }

/* Ordenar encostado na borda direita da barra: sem largura mínima herdada */
