.badges-box__item { position: relative; display: flex !important; align-items: center; gap: 12px !important; min-height: 56px; padding: 8px !important; border-radius: 8px !important; }
.badges-box__item + .badges-box__item::before { content: ""; position: absolute; top: 0; left: 8px; right: 8px; height: 1px; background: rgba(0, 0, 0, 0.051); }
.badges-box__item:hover::before, .badges-box__item:hover + .badges-box__item::before { opacity: 0; }
.badges-box__item-icon { width: 40px !important; height: 40px !important; flex: none; display: flex !important; align-items: center; justify-content: center; border-radius: 8px;
  background: var(--ctl-bg); box-shadow: 0 0 0 1px rgba(255, 255, 255, .08); }
.badges-box__item-icon img { width: 28px !important; height: 28px !important; }
.badges-box__item-content { min-width: 0; display: flex; flex-direction: column; gap: 0; }
.badges-box__item-title { margin: 0 !important; font: 400 14px/20px var(--font) !important; color: var(--text) !important; }
.badges-box__item-description { margin: 0 !important; font: 400 12px/16px var(--font) !important; color: var(--text-3) !important; }
.user-stats__list-item { text-align: left !important; }
.profile-content__right-content :is(.profile-section__header, .profile-section__content, .user-stats__box, .badges-box__box, .user-stats__list, .badges-box__list) { background: transparent !important; }
.profile-section__button { width: 100% !important; }
.profile-section__button > :not(svg) { margin-right: auto; }
.profile-section__button svg { width: 16px; height: 16px; color: var(--text-2); }

/* Perfil — cabeçalho das seções: título, contador e seta à direita (como no jogo) */
.profile-section__button { flex-direction: row !important; justify-content: flex-start !important; }
.profile-section__button > span:first-of-type { order: 1; margin-right: 0 !important; }
.profile-section__button > .profile-section__count { order: 2; margin-right: 0 !important; }
.profile-section__button > svg { order: 3; margin-left: auto !important; }
/* Atividades recentes e Amigos: linhas como a lista de conquistas do jogo */
:is(.recent-games__box, .friends-box__box) { padding: 0 !important; background: none !important; border: 0 !important; }
:is(.recent-games__list, .friends-box__list) { display: flex !important; flex-direction: column; gap: 0 !important; padding: 0 8px 8px !important; margin: 0 !important; list-style: none; }
:is(.recent-games__list, .friends-box__list) > li { position: relative; }
:is(.recent-games__list, .friends-box__list) > li + li::before { content: ""; position: absolute; top: 0; left: 8px; right: 8px; height: 1px; background: rgba(0, 0, 0, 0.051); z-index: 1; }
:is(.recent-games__list, .friends-box__list) > li:hover::before, :is(.recent-games__list, .friends-box__list) > li:hover + li::before { opacity: 0; }
