.game-details__review-score-stars:not(:is([title="Muito Negativo"],[title="Very Negative"],[title="Negativo"],[title="Negative"],[title="Neutro"],[title="Neutral"],[title="Positivo"],[title="Positive"],[title="Muito Positivo"],[title="Very Positive"])) > svg { display: inline-block; }
.game-details__review-score-stars:not(:is([title="Muito Negativo"],[title="Very Negative"],[title="Negativo"],[title="Negative"],[title="Neutro"],[title="Neutral"],[title="Positivo"],[title="Positive"],[title="Muito Positivo"],[title="Very Positive"])) .game-details__review-score-text { display: inline; }

/* ---------- Acessibilidade ---------- */
/* Menos movimento no Windows: nada desliza, aproxima ou sobe (vale sobre
   qualquer regra do tema, por isso o seletor forte e !important). */
@media (prefers-reduced-motion: reduce) {
  html body *, html body *::before, html body *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important; animation-delay: 0s !important;
    transition-duration: .01ms !important; scroll-behavior: auto !important;
  }
  html body :is(.game-card, .game-card__cover, .library-game-card-large, .library-game-card-large__background, .game-item-classics, .game-item-classics__cover-image,
    .console-card, .console-card__art-image, .profile-content__souvenir, .profile-hero__avatar-button, .similar-games__card, .similar-games__card img, .hero__media,
    .vertical-cover-card, .game-item__cover-wrapper img):is(:hover, *) { transform: none !important; }
}
