  font: 600 11px/18px var(--font) !important; background: color-mix(in srgb, var(--accent-bright) 16%, transparent) !important; color: var(--accent-bright) !important; }
.notifications__actions { display: flex !important; gap: 8px !important; margin-left: auto; }
.notifications__actions .button {
  height: 32px !important; min-height: 32px !important; padding: 0 12px !important; font: var(--ctl-font) !important; border-radius: var(--ctl-r) !important;
  background: var(--ctl-bg) !important; border: 1px solid var(--ctl-stroke) !important; color: var(--text) !important;
}
.notifications__actions .button:hover { background: var(--ctl-bg-hover) !important; }
.notifications__actions .button--danger { background: transparent !important; border-color: transparent !important; color: #c42b1c !important; }
.notifications__actions .button--danger:hover { background: rgba(196, 43, 28, .1) !important; }

.notifications__list { display: flex !important; flex-direction: column; gap: 0 !important; padding: 4px !important;
  background: rgba(0, 0, 0, 0.043); border: 1px solid rgba(0, 0, 0, 0.06); border-radius: 14px; }
.notification-item {
