.user-stats__list { display: grid !important; grid-template-columns: 1fr 1fr; gap: 8px !important; padding: 0 12px 12px !important; }
.user-stats__list-item { position: relative; display: flex !important; align-items: flex-start !important; justify-content: flex-end !important; min-height: 0 !important; border: 0 !important; border-radius: 10px !important; background: rgba(0, 0, 0, 0.03) !important; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.043); }
