.home__header > .button {
  border-radius: 999px !important; border: 1px solid color-mix(in srgb, var(--accent-bright) 35%, transparent) !important;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 22%, transparent), color-mix(in srgb, var(--accent) 6%, transparent)) !important;
